class UnionFind {
  #parent;
  #rank;
  #components;

  constructor(n) {
    this.#parent     = Array.from({ length: n }, (_, i) => i);
    this.#rank       = new Array(n).fill(0);
    this.#components = n;
  }

  // O(α(n)) amortised — path compression
  find(x) {
    if (this.#parent[x] !== x)
      this.#parent[x] = this.find(this.#parent[x]); // compress path
    return this.#parent[x];
  }

  // O(α(n)) — union by rank
  union(a, b) {
    const ra = this.find(a);
    const rb = this.find(b);
    if (ra === rb) return false; // already same set
    if (this.#rank[ra] < this.#rank[rb]) {
      this.#parent[ra] = rb;
    } else if (this.#rank[ra] > this.#rank[rb]) {
      this.#parent[rb] = ra;
    } else {
      this.#parent[rb] = ra;
      this.#rank[ra]++;
    }
    this.#components--;
    return true; // merge happened
  }

  connected(a, b) { return this.find(a) === this.find(b); }
  count()         { return this.#components; }
}

// Cycle detection in undirected graph
function hasCycle(n, edges) {
  const uf = new UnionFind(n);
  for (const [u, v] of edges) {
    if (uf.connected(u, v)) return true; // adding edge creates cycle
    uf.union(u, v);
  }
  return false;
}

const uf = new UnionFind(6);
uf.union(0, 1); uf.union(1, 2); uf.union(3, 4);
console.log(uf.connected(0, 2)); // true
console.log(uf.connected(0, 3)); // false
console.log(uf.count());         // 3 (sets: {0,1,2}, {3,4}, {5})

console.log(hasCycle(4, [[0,1],[1,2],[2,3]]));         // false (tree)
console.log(hasCycle(4, [[0,1],[1,2],[2,3],[3,0]]));   // true  (cycle)

// Kruskal's Minimum Spanning Tree using Union-Find
// Greedy: sort edges by weight, add edge if it doesn't create a cycle

function kruskalMST(n, edges) {
  // edges: [[weight, u, v], ...]
  edges.sort((a, b) => a[0] - b[0]); // sort by weight ascending
  const uf  = new UnionFind(n);
  const mst = [];
  let   totalWeight = 0;

  for (const [w, u, v] of edges) {
    if (!uf.connected(u, v)) {  // no cycle
      uf.union(u, v);
      mst.push([u, v, w]);
      totalWeight += w;
      if (mst.length === n - 1) break; // MST complete
    }
  }
  return { mst, totalWeight };
}

// Example: 4 vertices, 5 edges
const edges = [
  [1, 0, 1],
  [4, 0, 2],
  [3, 1, 2],
  [2, 1, 3],
  [5, 2, 3]
];
const { mst, totalWeight } = kruskalMST(4, edges);
console.log('MST edges:', mst);           // [[0,1,1],[1,3,2],[1,2,3]]
console.log('Total weight:', totalWeight); // 6

